# Surah An-Naml (chapter 27) — part 4: ayat 31-40 (IDs 3190-3199)
SURAH = 27

ENTRIES = {
3190: (
"کہ میرے مقابلے میں سرکشی نہ کرو — اور میرے پاس فرمانبردار ہو کر آؤ",
"""۱۔ سلیمانؑ کا خط — سرکشی نہیں؛ اسلام قبول کرنا؛ حاضر ہو کر۔
۲۔ ’’أَلَّا تَعْلُوا عَلَيَّ وَأْتُونِي مُسْلِمِينَ‘‘ — کہ میرے مقابلے میں سرکشی نہ کرو — اور میرے پاس فرمانبردار ہو کر آؤ — یعنی کہ میرے مقابلے میں سرکشی نہ کرو اور میرے پاس فرمانبردار ہو کر آؤ۔
۳۔ عملی سبق: اللہ کے پیغام کے سامنے سر تسلیم خم کرو؛ تکبر سے بچو؛ ایمان لاؤ۔"""
),
3191: (
"اس نے کہا اے سردارو! میرے اس معاملے میں میری مدد کرو — میں کوئی فیصلہ نہیں کرتی جب تک تم حاضر نہ ہو",
"""۱۔ ملکہ سبا — مشورہ؛ سردار؛ فیصلہ۔
۲۔ ’’قَالَتْ يَا أَيُّهَا الْمَلَأُ أَفْتُونِي فِي أَمْرِي مَا كُنتُ قَاطِعَۃً أَمْرًا حَتَّىٰ تَشْهَدُونِ‘‘ — اس نے کہا اے سردارو! میرے اس معاملے میں میری مدد کرو — میں کوئی فیصلہ نہیں کرتی جب تک تم حاضر نہ ہو — یعنی اس نے کہا اے سردارو میرے اس معاملے میں میری مدد کرو میں کوئی فیصلہ نہیں کرتی جب تک تم حاضر نہ ہو۔
۳۔ عملی سبق: اہم فیصلے میں مشورہ کرو؛ اہل لوگوں کی رائے لو؛ جلد بازی سے بچو۔"""
),
3192: (
"انہوں نے کہا ہم طاقتور اور سخت جنگجو ہیں — اور حکم تمہارے ہاتھ میں ہے — پس دیکھو تمہیں کیا حکم کرنا ہے",
"""۱۔ سردار — طاقت؛ حکم ملکہ کے ہاتھ میں؛ مشورہ۔
۲۔ ’’قَالُوا نَحْنُ أُولُو قُوَّۃٍ وَأُولُو بَأْسٍ شَدِيدٍ وَالْأَمْرُ إِلَيْكِ فَانظُرِي مَاذَا تَأْمُرِينَ‘‘ — انہوں نے کہا ہم طاقتور اور سخت جنگجو ہیں — اور حکم تمہارے ہاتھ میں ہے — پس دیکھو تمہیں کیا حکم کرنا ہے — یعنی انہوں نے کہا ہم طاقتور اور سخت جنگجو ہیں اور حکم تمہارے ہاتھ میں ہے پس دیکھو تمہیں کیا حکم کرنا ہے۔
۳۔ عملی سبق: مشورہ دیں، فیصلہ ملکہ سے؛ خود مختاری کی عزت کرو؛ طاقت کا صحیح استعمال کرو۔"""
),
3193: (
"اس نے کہا بے شک بادشاہ جب کسی بستی میں داخل ہوتے ہیں اسے تباہ و برباد کر دیتے ہیں — اور اس کے معزز لوگوں کو ذلیل کر دیتے ہیں — اور یہی وہ کرتے ہیں",
"""۱۔ ملکہ سبا — بادشاہوں کی تباہ کاری؛ حکمت؛ مشاہدہ۔
۲۔ ’’قَالَتْ إِنَّ الْمُلُوكَ إِذَا دَخَلُوا قَرْيَۃً أَفْسَدُوهَا وَجَعَلُوا أَعِزَّۃَ أَهْلِهَا أَذِلَّۃً وَكَذَٰلِكَ يَفْعَلُونَ‘‘ — اس نے کہا بے شک بادشاہ جب کسی بستی میں داخل ہوتے ہیں اسے تباہ و برباد کر دیتے ہیں — اور اس کے معزز لوگوں کو ذلیل کر دیتے ہیں — اور یہی وہ کرتے ہیں — یعنی اس نے کہا بے شک بادشاہ جب کسی بستی میں داخل ہوتے ہیں اسے تباہ و برباد کر دیتے ہیں اور اس کے معزز لوگوں کو ذلیل کر دیتے ہیں اور یہی وہ کرتے ہیں۔
۳۔ عملی سبق: ظلم کرنے والوں سے بچو؛ جنگ سے گریز کرو؛ امن کی راہ تلاش کرو۔"""
),
3194: (
"اور میں ان کے پاس ایک تحفہ بھیجوں گی — پس دیکھوں گی قاصد کیا واپس آتے ہیں",
"""۱۔ ملکہ سبا — تحفہ؛ قاصد؛ جواب کا انتظار۔
۲۔ ’’وَإِنِّي مُرْسِلَۃٌ إِلَيْهِم بِهَدِيَّۃٍ فَنَاظِرَۃٌ بِمَ يَرْجِعُ الْمُرْسَلُونَ‘‘ — اور میں ان کے پاس ایک تحفہ بھیجوں گی — پس دیکھوں گی قاصد کیا واپس آتے ہیں — یعنی اور میں ان کے پاس ایک تحفہ بھیجوں گی پس دیکھوں گی قاصد کیا واپس آتے ہیں۔
۳۔ عملی سبق: مسائل میں سفارتکاری سے کام لو؛ غور و فکر کرو؛ جلد بازی سے بچو۔"""
),
3195: (
"پس جب وہ سلیمانؑ کے پاس آیا تو اس نے کہا کیا تم مجھے مال سے مدد دیتے ہو؟ — جو اللہ نے مجھے دیا ہے وہ تمہارے دیے سے بہتر ہے — بلکہ تم اپنے تحفے پر خوش ہوتے ہو",
"""۱۔ سلیمانؑ — تحفہ مسترد؛ اللہ کی نعمت؛ بے نیازی۔
۲۔ ’’فَلَمَّا جَاءَ سُلَيْمَانَ قَالَ أَتُمِدُّونَنِ بِمَالٍ فَمَا آتَانِيَ اللَّهُ خَيْرٌ مِّمَّا آتَاكُم بَلْ أَنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ‘‘ — پس جب وہ سلیمانؑ کے پاس آیا تو اس نے کہا کیا تم مجھے مال سے مدد دیتے ہو؟ — جو اللہ نے مجھے دیا ہے وہ تمہارے دیے سے بہتر ہے — بلکہ تم اپنے تحفے پر خوش ہوتے ہو — یعنی پس جب وہ سلیمانؑ کے پاس آیا تو اس نے کہا کیا تم مجھے مال سے مدد دیتے ہو جو اللہ نے مجھے دیا ہے وہ تمہارے دیے سے بہتر ہے بلکہ تم اپنے تحفے پر خوش ہوتے ہو۔
۳۔ عملی سبق: اللہ کی دی ہوئی نعمتوں پر شکر کرو؛ دنیاوی لالچ سے بے نیاز رہو۔"""
),
3196: (
"ان کے پاس واپس جاؤ — پس ہم ان کے پاس ایسا لشکر لائیں گے جس کا ان میں مقابلہ نہیں کر سکتے — اور ہم انہیں اس سے ذلیل ہو کر نکال دیں گے",
"""۱۔ سلیمانؑ — عزم؛ لشکر؛ ذلت؛ تنبیہ۔
۲۔ ’’ارْجِعْ إِلَيْهِمْ فَلَنَأْتِيَنَّهُم بِجُنُودٍ لَّا قِبَلَ لَهُم بِهَا وَلَنُخْرِجَنَّهُم مِّنْهَا أَذِلَّۃً وَهُمْ صَاغِرُونَ‘‘ — ان کے پاس واپس جاؤ — پس ہم ان کے پاس ایسا لشکر لائیں گے جس کا ان میں مقابلہ نہیں کر سکتے — اور ہم انہیں اس سے ذلیل ہو کر نکال دیں گے — یعنی ان کے پاس واپس جاؤ پس ہم ان کے پاس ایسا لشکر لائیں گے جس کا ان میں مقابلہ نہیں کر سکتے اور ہم انہیں اس سے ذلیل ہو کر نکال دیں گے۔
۳۔ عملی سبق: ظالموں کو تنبیہ کرو؛ اللہ کی مدد پر بھروسہ رکھو؛ ردِ عمل سے بچو۔"""
),
3197: (
"اس نے کہا اے سردارو! کون تم میں سے اس کا تخت میرے پاس لاتا ہے اس سے پہلے کہ وہ میرے پاس فرمانبردار ہو کر آئیں",
"""۱۔ سلیمانؑ — تختِ بلقیس؛ چیلنج؛ فرما نبرداری۔
۲۔ ’’قَالَ يَا أَيُّهَا الْمَلَأُ أَيُّكُمْ يَأْتِينِي بِعَرْشِهَا قَبْلَ أَن يَأْتُونِي مُسْلِمِينَ‘‘ — اس نے کہا اے سردارو! کون تم میں سے اس کا تخت میرے پاس لاتا ہے اس سے پہلے کہ وہ میرے پاس فرمانبردار ہو کر آئیں — یعنی اس نے کہا اے سردارو کون تم میں سے اس کا تخت میرے پاس لاتا ہے اس سے پہلے کہ وہ میرے پاس فرمانبردار ہو کر آئیں۔
۳۔ عملی سبق: اللہ کی قدرت کے مظاہر پر غور کرو؛ ایمان لاؤ؛ تکبر سے بچو۔"""
),
3198: (
"ایک جن نے کہا میں اسے آپ کے پاس لے آؤں گا اس سے پہلے کہ آپ اپنی جگہ سے اٹھیں — اور میں اس پر طاقتور اور امانت دار ہوں",
"""۱۔ عفریت — عزم؛ طاقت؛ امانت۔
۲۔ ’’قَالَ عِفْرِيتٌ مِّنَ الْجِنِّ أَنَا آتِيكَ بِهِ قَبْلَ أَن تَقُومَ مِن مَّقَامِكَ وَإِنِّي عَلَيْهِ لَقَوِيٌّ أَمِينٌ‘‘ — ایک جن نے کہا میں اسے آپ کے پاس لے آؤں گا اس سے پہلے کہ آپ اپنی جگہ سے اٹھیں — اور میں اس پر طاقتور اور امانت دار ہوں — یعنی ایک جن نے کہا میں اسے آپ کے پاس لے آؤں گا اس سے پہلے کہ آپ اپنی جگہ سے اٹھیں اور میں اس پر طاقتور اور امانت دار ہوں۔
۳۔ عملی سبق: اپنی طاقت کا گھمنڈ نہ کرو؛ امانت داری سے کام لو؛ اللہ سے ڈرتے رہو۔"""
),
3199: (
"جس کے پاس کتاب کا علم تھا اس نے کہا میں اسے آپ کے پاس لے آؤں گا اس سے پہلے کہ آپ کی پلک جھپکے — پس جب اسے اپنے پاس ٹھہرا ہوا دیکھا تو اس نے کہا یہ میرے رب کا فضل ہے تاکہ مجھے آزمائے کہ میں شکر کرتا ہوں یا ناشکری — اور جو شکری کرتا ہے وہ اپنے فائدہ کے لیے شکری کرتا ہے — اور جو ناشکری کرتا ہے تو میرا رب بے نیاز و کریم ہے",
"""۱۔ کتاب کا علم والا — لمحہ بھر میں؛ اللہ کا فضل؛ امتحان؛ شکر؛ بے نیازی۔
۲۔ ’’قَالَ الَّذِي عِندَهُ عِلْمٌ مِّنَ الْكِتَابِ أَنَا آتِيكَ بِهِ قَبْلَ أَن يَرْتَدَّ إِلَيْكَ طَرْفُكَ فَلَمَّا رَآهُ مُسْتَقِرًّا عِندَهُ قَالَ هَٰذَا مِن فَضْلِ رَبِّي لِيَبْلُوَنِي أَأَشْكُرُ أَمْ أَكْفُرُ وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيٌّ كَرِيمٌ‘‘ — جس کے پاس کتاب کا علم تھا اس نے کہا میں اسے آپ کے پاس لے آؤں گا اس سے پہلے کہ آپ کی پلک جھپکے — پس جب اسے اپنے پاس ٹھہرا ہوا دیکھا تو اس نے کہا یہ میرے رب کا فضل ہے تاکہ مجھے آزمائے کہ میں شکر کرتا ہوں یا ناشکری — اور جو شکری کرتا ہے وہ اپنے فائدہ کے لیے شکری کرتا ہے — اور جو ناشکری کرتا ہے تو میرا رب بے نیاز و کریم ہے — یعنی جس کے پاس کتاب کا علم تھا اس نے کہا میں اسے آپ کے پاس لے آؤں گا اس سے پہلے کہ آپ کی پلک جھپکے پس جب اسے اپنے پاس ٹھہرا ہوا دیکھا تو اس نے کہا یہ میرے رب کا فضل ہے تاکہ مجھے آزمائے کہ میں شکر کرتا ہوں یا ناشکری اور جو شکری کرتا ہے وہ اپنے فائدہ کے لیے شکری کرتا ہے اور جو ناشکری کرتا ہے تو میرا رب بے نیاز و کریم ہے۔
۳۔ عملی سبق: اللہ کا شکر کرو؛ اس کی نعمتوں کو اپنا کمال نہ سمجھو؛ بے نیازی مانو۔"""
),
}
